export const DUA = [
  {"id":"D01","title":"On waking in the morning","ar":"اَللّٰهُمَّ بِكَ اَصْبَحْنَا وَبِكَ اَمْسَيْنَا وَبِكَ نَحْيَا وَبِكَ نَمُوْتُ وَاِلَيْكَ الْمَصِيْرُ","tr":"Allahumma bika asbahna, wa bika amsayna, wa bika nahya, wa bika namutu, wa ilaykal-masir.","en":"O Allah, by You we reach the morning and by You we reach the evening. By You we live and by You we die, and to You is the return.","narrator":"Abū Hurayrah","collection":"Abu Dawood and Tirmizi","src":"Maʿārif al-Hadīth, vol. 3, p. 150","draft":false,"status":"approved"},
  {"id":"D02","title":"The good of this day","ar":"اَصْبَحْنَا وَاَصْبَحَ الْمُلْكُ لِلّٰهِ رَبِّ الْعَالَمِيْنَ اَللّٰهُمَّ اِنِّىْ اَسْئَلُكَ خَيْرَ هٰذَا الْيَوْمِ وَفَتْحَهٗ وَنَصْرَهٗ وَنُوْرَهٗ وَبَرَكَتَهٗ وَهُدَاهُ وَاَعُوْذُ بِكَ مِنْ شَرِّ مَا فِيْهِ وَشَرِّ مَا بَعْدَهٗ","tr":"Asbahna wa asbahal-mulku lillahi rabbil-'alamin. Allahumma inni as'aluka khayra hadhal-yawmi, fat-hahu wa nasrahu wa nurahu wa barakatahu wa hudahu, wa a'udhu bika min sharri ma fihi wa sharri ma ba'dah.","en":"We have reached the morning, and the whole dominion belongs to Allah, Lord of the worlds. O Allah, I ask You for the good of this day: its openings, its help, its light, its blessing and its guidance. And I seek refuge in You from the evil in it and the evil that comes after it.","narrator":"Abū Mālik al-Ashʿarī","collection":"Abu Dawood","src":"Maʿārif al-Hadīth, vol. 3, p. 155","draft":false,"status":"approved"},
  {"id":"D03","title":"Thanks at bedtime","ar":"اَلْحَمْدُ لِلّٰهِ الَّذِىْ اَطْعَمَنَا وَسَقَانَا وَكَفَانَا وَاٰوَانَا فَكَمْ مِمَّنْ لَا كَافِىَ لَهٗ وَلَا مُؤْوِىَ","tr":"Alhamdu lillahil-ladhi at'amana wa saqana wa kafana wa awana, fa kam mimman la kafiya lahu wa la mu'wi.","en":"All praise is for Allah, who fed us, gave us drink, saw to our needs and gave us a home. How many there are with no one to provide for them and no one to give them shelter.","narrator":"Anas","collection":"Muslim","src":"Maʿārif al-Hadīth, vol. 3, p. 159","draft":false,"status":"approved"},
  {"id":"D04","title":"Sleeping and waking","ar":"اَللّٰهُمَّ بِاسْمِكَ اَمُوْتُ وَاَحْيٰ ۔ اَلْحَمْدُ لِلّٰهِ الَّذِىْ اَحْيَانَا بَعْدَ مَا اَمَاتَنَا وَاِلَيْهِ النُّشُوْرُ","tr":"(On lying down) Allahumma bismika amutu wa ahya. (On waking) Alhamdu lillahil-ladhi ahyana ba'da ma amatana wa ilayhin-nushur.","en":"On lying down: O Allah, in Your name I die and I live. On waking: All praise is for Allah, who gave us life after He had made us die, and to Him is the rising.","narrator":"Hudhayfah","collection":"Bukhari (the book adds that Muslim has it from al-Barāʾ ibn ʿĀzib)","src":"Maʿārif al-Hadīth, vol. 3, p. 159","draft":false,"status":"approved"},
  {"id":"D05","title":"Last words before sleep","ar":"اَللّٰهُمَّ اَسْلَمْتُ وَجْهِىْ اِلَيْكَ وَفَوَّضْتُ اَمْرِىْ اِلَيْكَ وَاَلْجَاْتُ ظَهْرِىْ اِلَيْكَ رَهْبَةً وَّرَغْبَةً اِلَيْكَ لَا مَلْجَاَ وَلَا مَنْجَاَ مِنْكَ اِلَّا اِلَيْكَ اٰمَنْتُ بِكِتَابِكَ الَّذِىْ اَنْزَلْتَ وَنَبِيِّكَ الَّذِىْ اَرْسَلْتَ","tr":"Allahumma aslamtu wajhi ilayk, wa fawwadtu amri ilayk, wa alja'tu zahri ilayk, rahbatan wa raghbatan ilayk. La malja'a wa la manja minka illa ilayk. Amantu bi kitabikal-ladhi anzalta wa nabiyyikal-ladhi arsalt.","en":"O Allah, I have turned my face to You, handed my affairs to You and leant my back on You, in awe of You and longing for You. There is no refuge and no escape from You except to You. I believe in Your Book which You sent down, and in Your Prophet whom You sent.","narrator":"al-Barāʾ ibn ʿĀzib","collection":"Bukhari and Muslim","src":"Maʿārif al-Hadīth, vol. 3, p. 160","draft":false,"status":"approved"},
  {"id":"D06","title":"After a bad dream","ar":"اَعُوْذُ بِكَلِمَاتِ اللهِ التَّامَّاتِ مِنْ غَضَبِهٖ وَعَذَابِهٖ وَمِنْ شَرِّ عِبَادِهٖ وَمِنْ هَمَزَاتِ الشَّيَاطِيْنِ وَاَنْ يَّحْضُرُوْنَ","tr":"A'udhu bi kalimatillahit-tammati min ghadabihi wa 'adhabihi, wa min sharri 'ibadihi, wa min hamazatish-shayatini wa an yahdurun.","en":"I seek refuge in Allah's perfect words from His anger and His punishment, from the evil of His servants, from the promptings of the devils, and from their coming near me.","narrator":"ʿAbdullāh ibn ʿAmr ibn al-ʿĀs","collection":"Abu Dawood and Tirmizi","src":"Maʿārif al-Hadīth, vol. 3, p. 165","draft":false,"status":"approved"},
  {"id":"D07","title":"Entering the toilet","ar":"اَللّٰهُمَّ اِنِّىْ اَعُوْذُ بِكَ مِنَ الْخُبُثِ وَالْخَبَائِثِ","tr":"Allahumma inni a'udhu bika minal-khubuthi wal-khaba'ith.","en":"O Allah, I seek refuge in You from the unclean devils, male and female.","narrator":"Anas","collection":"Bukhari and Muslim","src":"Maʿārif al-Hadīth, vol. 3, p. 169","draft":false,"status":"approved"},
  {"id":"D08","title":"Leaving the toilet","ar":"اَلْحَمْدُ لِلّٰهِ الَّذِىْ اَذْهَبَ عَنِّى الْاَذٰى وَعَافَانِىْ","tr":"Alhamdu lillahil-ladhi adhhaba 'anniyal-adha wa 'afani.","en":"All praise is for Allah, who took the harm away from me and kept me well.","narrator":"Anas","collection":"Ibn Majah","src":"Maʿārif al-Hadīth, vol. 3, p. 169","draft":false,"status":"approved"},
  {"id":"D09","title":"Stepping out of the house","ar":"بِسْمِ اللهِ تَوَكَّلْتُ عَلَى اللهِ لَا حَوْلَ وَلَا قُوَّةَ اِلَّا بِاللهِ","tr":"Bismillahi, tawakkaltu 'alallah, la hawla wa la quwwata illa billah.","en":"In the name of Allah. I put my trust in Allah. There is no power and no strength except through Allah.","narrator":"Anas","collection":"Tirmizi and Abu Dawood","src":"Maʿārif al-Hadīth, vol. 3, p. 170","draft":false,"status":"approved"},
  {"id":"D10","title":"Safe from wrong on the way","ar":"بِسْمِ اللهِ تَوَكَّلْتُ عَلَى اللهِ اَللّٰهُمَّ اِنَّا نَعُوْذُ بِكَ مِنْ اَنْ نَّزِلَّ اَوْ نَضِلَّ اَوْ نَظْلِمَ اَوْ يُظْلَمَ عَلَيْنَا اَوْ نَجْهَلَ اَوْ يُجْهَلَ عَلَيْنَا","tr":"Bismillahi, tawakkaltu 'alallah. Allahumma inna na'udhu bika min an nazilla aw nadilla, aw nazlima aw yuzlama 'alayna, aw najhala aw yujhala 'alayna.","en":"In the name of Allah. I put my trust in Allah. O Allah, we seek refuge in You from slipping or going astray, from wronging others or being wronged, and from acting foolishly or being treated foolishly.","narrator":"Umm Salamah","collection":"Ahmad, Tirmizi and Nasa'i","src":"Maʿārif al-Hadīth, vol. 3, p. 171","draft":false,"status":"approved"},
  {"id":"D11","title":"Coming home","ar":"اَللّٰهُمَّ اَسْئَلُكَ خَيْرَ الْمَوْلِجِ وَخَيْرَ الْمَخْرَجِ بِسْمِ اللهِ وَلَجْنَا وَبِسْمِ اللهِ خَرَجْنَا وَعَلَى اللهِ رَبِّنَا تَوَكَّلْنَا","tr":"Allahumma as'aluka khayral-mawliji wa khayral-makhraj. Bismillahi walajna, wa bismillahi kharajna, wa 'alallahi rabbina tawakkalna.","en":"O Allah, I ask You for the good of coming in and the good of going out. In the name of Allah we come in, in the name of Allah we go out, and in Allah our Lord we put our trust.","narrator":"Abū Mālik al-Ashʿarī","collection":"Abu Dawood","src":"Maʿārif al-Hadīth, vol. 3, pp. 171–172","draft":false,"status":"approved"},
  {"id":"D12","title":"Entering and leaving the masjid","ar":"اَللّٰهُمَّ افْتَحْ لِىْ اَبْوَابَ رَحْمَتِكَ ۔ اَللّٰهُمَّ اِنِّىْ اَسْئَلُكَ مِنْ فَضْلِكَ","tr":"(Going in) Allahummaftah li abwaba rahmatik. (Coming out) Allahumma inni as'aluka min fadlik.","en":"Going in: O Allah, open for me the doors of Your mercy. Coming out: O Allah, I ask You for Your bounty.","narrator":"Abū Usayd","collection":"Muslim","src":"Maʿārif al-Hadīth, vol. 3, p. 173","draft":false,"status":"approved"},
  {"id":"D13","title":"Before leaving a gathering","ar":"سُبْحَانَكَ اَللّٰهُمَّ وَبِحَمْدِكَ اَشْهَدُ اَنْ لَّا اِلٰهَ اِلَّا اَنْتَ اَسْتَغْفِرُكَ وَاَتُوْبُ اِلَيْكَ","tr":"Subhanakallahumma wa bihamdik, ash-hadu an la ilaha illa ant, astaghfiruka wa atubu ilayk.","en":"Glory be to You, O Allah, and praise. I bear witness that there is no god but You. I ask Your forgiveness and I turn to You.","narrator":"Abū Hurayrah","collection":"Tirmizi","src":"Maʿārif al-Hadīth, vol. 3, p. 174","draft":false,"status":"approved"},
  {"id":"D14","title":"Going to the market","ar":"بِسْمِ اللهِ اَللّٰهُمَّ اِنِّىْ اَسْئَلُكَ خَيْرَ هٰذِهِ السُّوْقِ وَخَيْرَ مَا فِيْهَا وَاَعُوْذُ بِكَ مِنْ شَرِّهَا وَشَرِّ مَا فِيْهَا اَللّٰهُمَّ اِنِّىْ اَعُوْذُ بِكَ اَنْ اُصِيْبَ فِيْهَا صَفْقَةً خَاسِرَةً","tr":"Bismillah. Allahumma inni as'aluka khayra hadhihis-suqi wa khayra ma fiha, wa a'udhu bika min sharriha wa sharri ma fiha. Allahumma inni a'udhu bika an usiba fiha safqatan khasirah.","en":"In the name of Allah. O Allah, I ask You for the good of this market and the good of what is in it, and I seek refuge in You from its evil and the evil of what is in it. O Allah, I seek refuge in You from making a losing deal in it.","narrator":"Buraydah","collection":"Bayhaqi (in al-Daʿawāt al-Kabīr)","src":"Maʿārif al-Hadīth, vol. 3, p. 177","draft":false,"status":"approved"},
  {"id":"D15","title":"On seeing someone in trouble","ar":"اَلْحَمْدُ لِلّٰهِ الَّذِىْ عَافَانِىْ مِمَّا ابْتَلَاكَ بِهٖ وَفَضَّلَنِىْ عَلٰى كَثِيْرٍ مِّمَّنْ خَلَقَ تَفْضِيْلًا","tr":"Alhamdu lillahil-ladhi 'afani mimmab-talaka bihi, wa faddalani 'ala kathirin mimman khalaqa tafdila.","en":"All praise is for Allah, who has kept me safe from what He has tried you with, and has favoured me over many of those He created.","narrator":"ʿUmar ibn al-Khattāb and Abū Hurayrah","collection":"Tirmizi","src":"Maʿārif al-Hadīth, vol. 3, p. 180","draft":false,"status":"approved"},
  {"id":"D16","title":"After eating or drinking","ar":"اَلْحَمْدُ لِلّٰهِ الَّذِىْ اَطْعَمَنَا وَسَقَانَا وَجَعَلَنَا مِنَ الْمُسْلِمِيْنَ","tr":"Alhamdu lillahil-ladhi at'amana wa saqana wa ja'alana minal-muslimin.","en":"All praise is for Allah, who gave us food and drink and made us Muslims.","narrator":"Abū Saʿīd al-Khudrī","collection":"Abu Dawood and Tirmizi","src":"Maʿārif al-Hadīth, vol. 3, p. 181","draft":false,"status":"approved"},
  {"id":"D17","title":"Not by my own strength","ar":"اَلْحَمْدُ لِلّٰهِ الَّذِىْ اَطْعَمَنِىْ هٰذَا الطَّعَامَ وَرَزَقَنِيْهِ مِنْ غَيْرِ حَوْلٍ مِّنِّىْ وَلَا قُوَّةٍ","tr":"Alhamdu lillahil-ladhi at'amani hadhat-ta'ama wa razaqanihi min ghayri hawlin minni wa la quwwah.","en":"All praise is for Allah, who fed me this food and provided it for me, without any power or strength of my own.","narrator":"Muʿādh ibn Anas","collection":"Tirmizi","src":"Maʿārif al-Hadīth, vol. 3, p. 181","draft":false,"status":"approved"},
  {"id":"D18","title":"For the one who fed you","ar":"اَفْطَرَ عِنْدَكُمُ الصَّائِمُوْنَ وَاَكَلَ طَعَامَكُمُ الْاَبْرَارُ وَصَلَّتْ عَلَيْكُمُ الْمَلَائِكَةُ","tr":"Aftara 'indakumus-sa'imun, wa akala ta'amakumul-abrar, wa sallat 'alaykumul-mala'ikah.","en":"May those who fast break their fast with you, may the righteous eat your food, and may the angels pray for you.","narrator":"Anas","collection":"Abu Dawood","src":"Maʿārif al-Hadīth, vol. 3, pp. 182–183","draft":false,"status":"approved"},
  {"id":"D19","title":"Blessing for a household","ar":"اَللّٰهُمَّ بَارِكْ لَهُمْ فِيْمَا رَزَقْتَهُمْ وَاغْفِرْ لَهُمْ وَارْحَمْهُمْ","tr":"Allahumma barik lahum fima razaqtahum, waghfir lahum warhamhum.","en":"O Allah, bless them in what You have provided for them, forgive them and have mercy on them.","narrator":"ʿAbdullāh ibn Busr","collection":"Muslim","src":"Maʿārif al-Hadīth, vol. 3, p. 183","draft":false,"status":"approved"},
  {"id":"D20","title":"Wearing new clothes","ar":"اَلْحَمْدُ لِلّٰهِ الَّذِىْ كَسَانِىْ مَا اُوَارِىْ بِهٖ عَوْرَتِىْ وَاَتَجَمَّلُ بِهٖ فِىْ حَيَاتِىْ","tr":"Alhamdu lillahil-ladhi kasani ma uwari bihi 'awrati wa atajammalu bihi fi hayati.","en":"All praise is for Allah, who clothed me with what covers my body and what I can look good in during my life.","narrator":"ʿUmar","collection":"Ahmad, Tirmizi and Ibn Majah","src":"Maʿārif al-Hadīth, vol. 3, pp. 184–185","draft":false,"status":"approved"},
  {"id":"D21","title":"Looking in the mirror","ar":"اَلْحَمْدُ لِلّٰهِ الَّذِىْ سَوّٰى خَلْقِىْ وَاَحْسَنَ صُوْرَتِىْ وَزَانَ مِنِّىْ مَا شَانَ مِنْ غَيْرِىْ","tr":"Alhamdu lillahil-ladhi sawwa khalqi, wa ahsana surati, wa zana minni ma shana min ghayri.","en":"All praise is for Allah, who formed me well, made my face beautiful, and made fine in me what He made plain in others.","narrator":"Anas","collection":"Bazzar","src":"Maʿārif al-Hadīth, vol. 3, p. 185","draft":false,"status":"approved"},
  {"id":"D22","title":"At the start of a marriage","ar":"اَللّٰهُمَّ اِنِّىْ اَسْئَلُكَ خَيْرَهَا وَخَيْرَ مَا جَبَلْتَهَا عَلَيْهِ وَاَعُوْذُ بِكَ مِنْ شَرِّهَا وَشَرِّ مَا جَبَلْتَهَا عَلَيْهِ","tr":"Allahumma inni as'aluka khayraha wa khayra ma jabaltaha 'alayh, wa a'udhu bika min sharriha wa sharri ma jabaltaha 'alayh.","en":"O Allah, I ask You for her good and the good of the nature You created her with, and I seek refuge in You from her harm and the harm of the nature You created her with.","narrator":"ʿAbdullāh ibn ʿAmr ibn al-ʿĀs","collection":"Abu Dawood and Ibn Majah","src":"Maʿārif al-Hadīth, vol. 3, pp. 185–186","draft":false,"status":"approved"},
  {"id":"D23","title":"Congratulating a newly married couple","ar":"بَارَكَ اللهُ لَكَ وَبَارَكَ عَلَيْكُمَا وَجَمَعَ بَيْنَكُمَا فِىْ خَيْرٍ","tr":"Barakallahu laka, wa baraka 'alaykuma, wa jama'a baynakuma fi khayr.","en":"May Allah bless you, may He send blessing on you both, and may He bring you together in good.","narrator":"Abū Hurayrah","collection":"Ahmad, Tirmizi, Abu Dawood and Ibn Majah","src":"Maʿārif al-Hadīth, vol. 3, p. 186","draft":false,"status":"approved"},
  {"id":"D24","title":"Setting out on a journey","ar":"سُبْحَانَ الَّذِىْ سَخَّرَ لَنَا هٰذَا وَمَا كُنَّا لَهٗ مُقْرِنِيْنَ وَاِنَّا اِلٰى رَبِّنَا لَمُنْقَلِبُوْنَ اَللّٰهُمَّ اِنَّا نَسْئَلُكَ فِىْ سَفَرِنَا هٰذَا الْبِرَّ وَالتَّقْوٰى وَمِنَ الْعَمَلِ مَا تَرْضٰى اَللّٰهُمَّ هَوِّنْ عَلَيْنَا سَفَرَنَا هٰذَا وَاطْوِ لَنَا بُعْدَهٗ اَللّٰهُمَّ اَنْتَ الصَّاحِبُ فِى السَّفَرِ وَالْخَلِيْفَةُ فِى الْاَهْلِ وَالْمَالِ اَللّٰهُمَّ اِنِّىْ اَعُوْذُ بِكَ مِنْ وَعْثَاءِ السَّفَرِ وَكَاٰبَةِ الْمَنْظَرِ وَسُوْءِ الْمُنْقَلَبِ فِى الْاَهْلِ وَالْمَالِ","tr":"Subhanal-ladhi sakhkhara lana hadha wa ma kunna lahu muqrinin, wa inna ila rabbina la munqalibun. Allahumma inna nas'aluka fi safarina hadhal-birra wat-taqwa, wa minal-'amali ma tarda. Allahumma hawwin 'alayna safarana hadha, watwi lana bu'dah. Allahumma antas-sahibu fis-safari wal-khalifatu fil-ahli wal-mal. Allahumma inni a'udhu bika min wa'tha'is-safari, wa ka'abatil-manzari, wa su'il-munqalabi fil-ahli wal-mal.","en":"Glory be to the One who made this ride serve us; we could never have managed it ourselves, and to our Lord we will surely return. O Allah, on this journey we ask You for goodness and taqwā, and for deeds that please You. O Allah, make this journey easy for us and shorten its distance. O Allah, You are the Companion on the journey and the One who looks after the family and wealth left behind. O Allah, I seek refuge in You from the hardship of travel, from seeing anything distressing, and from coming back to find harm in my family or wealth.","narrator":"ʿAbdullāh ibn ʿUmar","collection":"Muslim","src":"Maʿārif al-Hadīth, vol. 3, pp. 187–188","draft":false,"status":"approved"},
  {"id":"D25","title":"Holding fast to Allah when leaving","ar":"اٰمَنْتُ بِاللهِ اِعْتَصَمْتُ بِاللهِ تَوَكَّلْتُ عَلَى اللهِ لَا حَوْلَ وَلَا قُوَّةَ اِلَّا بِاللهِ","tr":"Amantu billah, i'tasamtu billah, tawakkaltu 'alallah, la hawla wa la quwwata illa billah.","en":"I believe in Allah. I hold fast to Allah. I put my trust in Allah. There is no power and no strength except through Allah.","narrator":"ʿUthmān","collection":"Ahmad","src":"Maʿārif al-Hadīth, vol. 3, pp. 190–191","draft":false,"status":"approved"},
  {"id":"D26","title":"Arriving in a new town","ar":"اَللّٰهُمَّ بَارِكْ لَنَا فِيْهَا ۔ اَللّٰهُمَّ ارْزُقْنَا جَنَاهَا وَحَبِّبْنَا اِلٰى اَهْلِهَا وَحَبِّبْ صَالِحِىْ اَهْلِهَا اِلَيْنَا","tr":"Allahumma barik lana fiha (three times). Allahummarzuqna janaha, wa habbibna ila ahliha, wa habbib salihi ahliha ilayna.","en":"O Allah, bless us in this place (three times). O Allah, give us of its good produce, make us loved by its people, and make its righteous people dear to us.","narrator":"ʿAbdullāh ibn ʿUmar","collection":"Tabarani (al-Awsat)","src":"Maʿārif al-Hadīth, vol. 3, p. 191","draft":false,"status":"approved"},
  {"id":"D27","title":"For someone setting out","ar":"اَللّٰهُمَّ اَطْوِ لَهُ الْبُعْدَ وَهَوِّنْ عَلَيْهِ السَّفَرَ","tr":"Allahummatwi lahul-bu'da wa hawwin 'alayhis-safar.","en":"O Allah, shorten the distance for him and make the journey easy for him.","narrator":"Abū Hurayrah","collection":"Tirmizi","src":"Maʿārif al-Hadīth, vol. 3, p. 192","draft":false,"status":"approved"},
  {"id":"D28","title":"Provision for the road","ar":"زَوَّدَكَ اللهُ التَّقْوٰى وَغَفَرَ ذَنْبَكَ وَيَسَّرَ لَكَ الْخَيْرَ حَيْثُ مَا كُنْتَ","tr":"Zawwadakallahut-taqwa, wa ghafara dhanbak, wa yassara lakal-khayra haythu ma kunt.","en":"May Allah give you taqwā as your provision, forgive your sins, and make good easy for you wherever you are.","narrator":"Anas","collection":"Tirmizi","src":"Maʿārif al-Hadīth, vol. 3, pp. 192–193","draft":false,"status":"approved"},
  {"id":"D29","title":"Saying goodbye","ar":"اَسْتَوْدِعُ اللهَ دِيْنَكُمْ وَاَمَانَتَكُمْ وَخَوَاتِيْمَ اَعْمَالِكُمْ","tr":"Astawdi'ullaha dinakum wa amanatakum wa khawatima a'malikum.","en":"I leave in Allah's keeping your faith, your trustworthiness, and the last of your deeds.","narrator":"ʿAbdullāh al-Khatmī","collection":"Abu Dawood","src":"Maʿārif al-Hadīth, vol. 3, p. 193","draft":false,"status":"approved"},
  {"id":"D30","title":"In a time of fear","ar":"اَللّٰهُمَّ اَسْتُرْ عَوْرَاتِنَا وَاٰمِنْ رَوْعَاتِنَا","tr":"Allahummastur 'awratina wa amin raw'atina.","en":"O Allah, cover our weak points and calm our fears.","narrator":"Abū Saʿīd al-Khudrī","collection":"Ahmad","src":"Maʿārif al-Hadīth, vol. 3, pp. 193–194","draft":false,"status":"approved"},
  {"id":"D31","title":"When anxiety comes","ar":"لَا اِلٰهَ اِلَّا اللهُ الْعَظِيْمُ الْحَلِيْمُ لَا اِلٰهَ اِلَّا اللهُ رَبُّ الْعَرْشِ الْعَظِيْمِ لَا اِلٰهَ اِلَّا اللهُ رَبُّ السَّمٰوَاتِ وَرَبُّ الْاَرْضِ رَبُّ الْعَرْشِ الْكَرِيْمِ","tr":"La ilaha illallahul-'azimul-halim. La ilaha illallahu rabbul-'arshil-'azim. La ilaha illallahu rabbus-samawati wa rabbul-ardi rabbul-'arshil-karim.","en":"There is no god but Allah, the Mighty, the Forbearing. There is no god but Allah, Lord of the Mighty Throne. There is no god but Allah, Lord of the heavens, Lord of the earth, Lord of the Noble Throne.","narrator":"Ibn ʿAbbās","collection":"Bukhari and Muslim","src":"Maʿārif al-Hadīth, vol. 3, p. 195","draft":false,"status":"approved"},
  {"id":"D32","title":"When something heavy lies ahead","ar":"حَسْبُنَا اللهُ وَنِعْمَ الْوَكِيْلُ","tr":"Hasbunallahu wa ni'mal-wakil.","en":"Allah is enough for us, and He is the best One to rely on.","narrator":"Abū Hurayrah","collection":"Ibn Mardawayh","src":"Maʿārif al-Hadīth, vol. 3, p. 199","draft":false,"status":"approved"},
  {"id":"D33","title":"When something good happens","ar":"اَلْحَمْدُ لِلّٰهِ الَّذِىْ بِنِعْمَتِهٖ تَتِمُّ الصَّالِحَاتُ","tr":"Alhamdu lillahil-ladhi bi ni'matihi tatimmus-salihat.","en":"All praise is for Allah, by whose favour good things are completed.","narrator":"ʿĀʾishah","collection":"Ibn al-Najjār","src":"Maʿārif al-Hadīth, vol. 3, p. 204","draft":false,"status":"approved"},
  {"id":"D34","title":"For someone who is ill","ar":"اَذْهِبِ الْبَاسَ رَبَّ النَّاسِ وَاشْفِ اَنْتَ الشَّافِىْ لَا شِفَاءَ اِلَّا شِفَاءُكَ شِفَاءً لَا يُغَادِرُ سُقْمًا","tr":"Adhhibil-ba'sa rabban-nas, washfi antash-shafi, la shifa'a illa shifa'uk, shifa'an la yughadiru suqma.","en":"Take away the harm, Lord of mankind, and heal, for You are the Healer. There is no healing but Your healing, a healing that leaves no illness behind.","narrator":"ʿĀʾishah","collection":"Bukhari and Muslim","src":"Maʿārif al-Hadīth, vol. 3, pp. 205–206","draft":false,"status":"approved"},
  {"id":"D35","title":"Ruqyah for the sick","ar":"بِسْمِ اللهِ اَرْقِيْكَ مِنْ كُلِّ شَيْئٍ يُؤْذِيْكَ مِنْ شَرِّ كُلِّ نَفْسٍ وَّ حَاسِدٍ اَللّٰهُ يَشْفِيْكَ بِسْمِ اللهِ اَرْقِيْكَ","tr":"Bismillahi arqika min kulli shay'in yu'dhika, min sharri kulli nafsin wa hasid. Allahu yashfik. Bismillahi arqik.","en":"In the name of Allah I recite over you, from everything that harms you, from the evil of every soul and every envious eye. May Allah heal you. In the name of Allah I recite over you.","narrator":"Abū Saʿīd al-Khudrī","collection":"Muslim","src":"Maʿārif al-Hadīth, vol. 3, p. 206","draft":false,"status":"approved"},
  {"id":"D36","title":"When someone sneezes","ar":"اَلْحَمْدُ لِلّٰهِ ۔ يَرْحَمُكَ اللهُ ۔ يَهْدِيْكُمُ اللهُ وَيُصْلِحُ بَالَكُمْ","tr":"(The one who sneezes) Alhamdu lillah. (The one who hears) Yarhamukallah. (The one who sneezed replies) Yahdikumullahu wa yuslihu balakum.","en":"The one who sneezes says: All praise is for Allah. His brother says: May Allah have mercy on you. He replies: May Allah guide you and set your affairs right.","narrator":"Abū Hurayrah","collection":"Bukhari","src":"Maʿārif al-Hadīth, vol. 3, p. 207","draft":false,"status":"approved"},
  {"id":"D37","title":"When thunder roars","ar":"اَللّٰهُمَّ لَا تَقْتُلْنَا بِغَضَبِكَ وَلَا تُهْلِكْنَا بِعَذَابِكَ وَعَافِنَا قَبْلَ ذَالِكَ","tr":"Allahumma la taqtulna bi ghadabik, wa la tuhlikna bi 'adhabik, wa 'afina qabla dhalik.","en":"O Allah, do not kill us with Your anger, do not destroy us with Your punishment, and keep us safe before that.","narrator":"ʿAbdullāh ibn ʿUmar","collection":"Ahmad and Tirmizi","src":"Maʿārif al-Hadīth, vol. 3, p. 210","draft":false,"status":"approved"},
  {"id":"D38","title":"A wind of mercy","ar":"اَللّٰهُمَّ اجْعَلْهَا رَحْمَةً وَّلَا تَجْعَلْهَا عَذَابًا اَللّٰهُمَّ اجْعَلْهَا رِيَاحًا وَّلَا تَجْعَلْهَا رِيْحًا","tr":"Allahummaj'alha rahmatan wa la taj'alha 'adhaba. Allahummaj'alha riyahan wa la taj'alha riha.","en":"O Allah, make it a mercy and do not make it a punishment. O Allah, make it winds of blessing, and not a wind of ruin.","narrator":"Ibn ʿAbbās","collection":"al-Shāfiʿī, and Bayhaqi in al-Daʿawāt al-Kabīr","src":"Maʿārif al-Hadīth, vol. 3, pp. 210–211","draft":false,"status":"approved"},
  {"id":"D39","title":"In a strong wind","ar":"اَللّٰهُمَّ اِنِّىْ اَسْئَلُكَ خَيْرَهَا وَخَيْرَ مَا فِيْهَا وَخَيْرَ مَا اُرْسِلَتْ بِهٖ وَاَعُوْذُ بِكَ مِنْ شَرِّهَا وَشَرِّ مَا فِيْهَا وَشَرِّ مَا اُرْسِلَتْ بِهٖ","tr":"Allahumma inni as'aluka khayraha wa khayra ma fiha wa khayra ma ursilat bih, wa a'udhu bika min sharriha wa sharri ma fiha wa sharri ma ursilat bih.","en":"O Allah, I ask You for the good of this wind, the good in it, and the good it was sent with. And I seek refuge in You from its evil, the evil in it, and the evil it was sent with.","narrator":"ʿĀʾishah","collection":"Bukhari and Muslim","src":"Maʿārif al-Hadīth, vol. 3, p. 211","draft":false,"status":"approved"},
  {"id":"D40","title":"When clouds gather","ar":"اَللّٰهُمَّ اِنِّىْ اَعُوْذُ بِكَ مِنْ شَرِّ مَا فِيْهِ ۔ اَللّٰهُمَّ سَقْيًا نَافِعًا","tr":"(On seeing clouds) Allahumma inni a'udhu bika min sharri ma fih. (If it rains) Allahumma saqyan nafi'a.","en":"On seeing clouds: O Allah, I seek refuge in You from the evil of what is in it. If it rains: O Allah, make it a beneficial watering.","narrator":"ʿĀʾishah","collection":"Abu Dawood, Nasa'i, Ibn Majah and al-Shāfiʿī","src":"Maʿārif al-Hadīth, vol. 3, p. 212","draft":false,"status":"approved"},
  {"id":"D41","title":"When the rain falls","ar":"اَللّٰهُمَّ صَيِّبًا نَافِعًا","tr":"Allahumma sayyiban nafi'a.","en":"O Allah, let it be a beneficial rain.","narrator":"ʿĀʾishah","collection":"Bukhari","src":"Maʿārif al-Hadīth, vol. 3, p. 212","draft":false,"status":"approved"},
  {"id":"D42","title":"Asking for rain","ar":"اَللّٰهُمَّ اسْقِ عِبَادَكَ وَبَهِيْمَتَكَ وَانْشُرْ رَحْمَتَكَ وَاَحْىِ بَلَدَكَ الْمَيِّتَ","tr":"Allahummasqi 'ibadaka wa bahimatak, wanshur rahmatak, wa ahyi baladakal-mayyit.","en":"O Allah, give water to Your servants and Your animals, spread Your mercy, and bring Your dead land back to life.","narrator":"ʿAmr ibn Shuʿayb (from his father, from his grandfather)","collection":"Muwatta Imam Malik and Abu Dawood","src":"Maʿārif al-Hadīth, vol. 3, p. 213","draft":false,"status":"approved"},
  {"id":"D43","title":"Seeing the new moon","ar":"اَللّٰهُمَّ اَهِلَّهٗ عَلَيْنَا بِالْاَمْنِ وَالْاِيْمَانِ وَالسَّلَامَةِ وَالْاِسْلَامِ رَبِّىْ وَرَبُّكَ اللهُ","tr":"Allahumma ahillahu 'alayna bil-amni wal-iman, was-salamati wal-islam. Rabbi wa rabbukallah.","en":"O Allah, let this new moon rise over us with safety and faith, with peace and Islam. (O moon,) my Lord and your Lord is Allah.","narrator":"Talhah ibn ʿUbaydullāh","collection":"Tirmizi","src":"Maʿārif al-Hadīth, vol. 3, pp. 213–214","draft":false,"status":"approved"},
  {"id":"D44","title":"A month of good","ar":"هِلَالُ خَيْرٍ وَّرُشْدٍ ۔ اٰمَنْتُ بِالَّذِىْ خَلَقَكَ ۔ اَلْحَمْدُ لِلّٰهِ الَّذِىْ ذَهَبَ بِشَهْرِ كَذَا وَجَاءَ بِشَهْرِ كَذَا","tr":"Hilalu khayrin wa rushd (three times). Amantu billadhi khalaqak (three times). Alhamdu lillahil-ladhi dhahaba bi shahri kadha wa ja'a bi shahri kadha.","en":"A moon of good and right guidance (three times). I believe in the One who created you (three times). All praise is for Allah, who has taken away such-and-such a month and brought such-and-such a month.","narrator":"Qatādah (as a report that reached him)","collection":"Abu Dawood","src":"Maʿārif al-Hadīth, vol. 3, pp. 214–215","draft":false,"status":"approved"},
  {"id":"D45","title":"On Laylat al-Qadr","ar":"اَللّٰهُمَّ اِنَّكَ عَفُوٌّ تُحِبُّ الْعَفْوَ فَاعْفُ عَنِّىْ","tr":"Allahumma innaka 'afuwwun tuhibbul-'afwa fa'fu 'anni.","en":"O Allah, You are the Pardoner, and You love to pardon, so pardon me.","narrator":"ʿĀʾishah","collection":"Tirmizi","src":"Maʿārif al-Hadīth, vol. 3, p. 215","draft":false,"status":"approved"},
  {"id":"D46","title":"For pain in the body","ar":"اَعُوْذُ بِاللهِ وَقُدْرَتِهٖ مِنْ شَرِّ مَا اَجِدُ وَاُحَاذِرُ","tr":"A'udhu billahi wa qudratihi min sharri ma ajidu wa uhadhir.","en":"I seek refuge in Allah and in His power from the evil of what I feel and what I fear.","narrator":"ʿUthmān ibn Abi al-ʿĀs al-Thaqafī","collection":"Muslim","src":"Maʿārif al-Hadīth, vol. 3, p. 263","draft":false,"status":"approved"},
  {"id":"D47","title":"Protection for children","ar":"اُعِيْذُكُمَا بِكَلِمَاتِ اللهِ التَّامَّةِ مِنْ كُلِّ شَيْطَانٍ وَّهَامَّةٍ وَمِنْ كُلِّ عَيْنٍ لَامَّةٍ","tr":"U'idhukuma bi kalimatillahit-tammati min kulli shaytanin wa hammah, wa min kulli 'aynin lammah.","en":"I place you both in the protection of Allah's perfect words, from every devil and every harmful creature, and from every evil eye.","narrator":"Ibn ʿAbbās","collection":"Tirmizi and Abu Dawood","src":"Maʿārif al-Hadīth, vol. 3, pp. 262–263","draft":false,"status":"approved"},
  {"id":"D48","title":"Waking in the night","ar":"لَا اِلٰهَ اِلَّا اللهُ وَحْدَهٗ لَا شَرِيْكَ لَهٗ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلٰى كُلِّ شَيْئٍ قَدِيْرٌ اَلْحَمْدُ لِلّٰهِ وَسُبْحَانَ اللهِ وَلَا اِلٰهَ اِلَّا اللهُ وَاللهُ اَكْبَرُ وَلَا حَوْلَ وَلَا قُوَّةَ اِلَّا بِاللهِ","tr":"La ilaha illallahu wahdahu la sharika lah, lahul-mulku wa lahul-hamd, wa huwa 'ala kulli shay'in qadir. Alhamdu lillah, wa subhanallah, wa la ilaha illallah, wallahu akbar, wa la hawla wa la quwwata illa billah.","en":"There is no god but Allah, alone, with no partner. His is the dominion and His is the praise, and He has power over all things. All praise is for Allah, glory be to Allah, there is no god but Allah, Allah is the Greatest, and there is no power and no strength except through Allah.","narrator":"ʿUbādah ibn al-Sāmit","collection":"Bukhari","src":"Maʿārif al-Hadīth, vol. 3, pp. 167–168","draft":false,"status":"approved"},
  {"id":"D49","title":"Remembering Allah in the market","ar":"لَا اِلٰهَ اِلَّا اللهُ وَحْدَهٗ لَا شَرِيْكَ لَهٗ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ يُحْيِىْ وَيُمِيْتُ وَهُوَ حَىٌّ لَّا يَمُوْتُ بِيَدِهِ الْخَيْرُ وَهُوَ عَلٰى كُلِّ شَيْئٍ قَدِيْرٌ","tr":"La ilaha illallahu wahdahu la sharika lah, lahul-mulku wa lahul-hamd, yuhyi wa yumitu wa huwa hayyun la yamut, bi yadihil-khayr, wa huwa 'ala kulli shay'in qadir.","en":"There is no god but Allah, alone, with no partner. His is the dominion and His is the praise. He gives life and causes death, and He is the Ever-Living who does not die. All good is in His Hand, and He has power over all things.","narrator":"ʿUmar","collection":"Tirmizi and Ibn Majah","src":"Maʿārif al-Hadīth, vol. 3, pp. 177–178","draft":false,"status":"approved"},
  {"id":"D50","title":"Asking for good rain","ar":"اَللّٰهُمَّ اسْقِنَا غَيْثًا مُّغِيْثًا مُرِيْئًا مُرِيْعًا نَافِعًا غَيْرَ ضَارٍ عَاجِلًا غَيْرَ اٰجِلٍ","tr":"Allahummasqina ghaythan mughithan muri'an muri'an nafi'an ghayra darr, 'ajilan ghayra ajil.","en":"O Allah, send us rain that brings relief, wholesome and making the land green, beneficial and not harmful, soon and not delayed.","narrator":"Jābir","collection":"Abu Dawood","src":"Maʿārif al-Hadīth, vol. 3, p. 213","draft":false,"status":"approved"},
  {"id":"D51","title":"Putting on clothes","ar":"اَلْحَمْدُ لِلّٰهِ الَّذِىْ كَسَانِىْ هٰذَا وَرَزَقَنِيْهِ مِنْ غَيْرِ حَوْلٍ مِّنِّىْ وَلَا قُوَّةٍ","tr":"Alhamdu lillahil-ladhi kasani hadha wa razaqanihi min ghayri hawlin minni wa la quwwah.","en":"All praise is for Allah, who clothed me with this and provided it for me, without any power or strength of my own.","narrator":"Muʿādh ibn Anas","collection":"Abu Dawood","src":"Maʿārif al-Hadīth, vol. 3, p. 182","draft":false,"status":"approved"},
  {"id":"D52","title":"When someone in power is a threat","ar":"اَللّٰهُمَّ رَبَّ السَّمٰوَاتِ السَّبْعِ وَرَبَّ الْعَرْشِ الْعَظِيْمِ كُنْ لِىْ جَارًا مِنْ شَرِّ فُلَانِ ابْنِ فُلَانٍ وَّ شَرِّ الْجِنِّ وَالْاِنْسِ وَاَتْبَاعِهِمْ اَنْ يَّفْرُطَ عَلَىَّ اَحَدٌ مِنْهُمْ اَوْ اَنْ يَّطْغٰى عَزَّ جَارُكَ وَجَلَّ ثَنَاؤُكَ وَلَا اِلٰهَ غَيْرُكَ","tr":"Allahumma rabbas-samawatis-sab'i wa rabbal-'arshil-'azim, kun li jaran min sharri fulanibni fulan, wa sharril-jinni wal-insi wa atba'ihim, an yafruta 'alayya ahadun minhum aw an yatgha. 'Azza jaruka wa jalla thana'uka wa la ilaha ghayruk.","en":"O Allah, Lord of the seven heavens and Lord of the Mighty Throne, be my protector from the harm of so-and-so son of so-and-so, and from the harm of jinn and people and their followers, so that none of them rushes against me or oversteps. Mighty is the one You protect, great is Your praise, and there is no god but You.","narrator":"ʿAbdullāh ibn Masʿūd","collection":"Tabarani (al-Kabīr)","src":"Maʿārif al-Hadīth, vol. 3, pp. 201–202","draft":false,"status":"approved"},
];
